1	//! inkseal 的库接口：对任意实现 [`std::io::Read`] 的输入计算 SHA-256 摘要。
2	//!
3	//! 摘要只取决于输入的原始字节，与命令行 `inkseal digest <文件>` 遵循同一内容规则。
4	
5	use sha2::{Digest, Sha256};
6	use std::error::Error;
7	use std::fmt;
8	use std::io::{self, Read};
9	
10	/// SHA-256 摘要结果，可表示为 64 个小写十六进制字符。
11	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
12	pub struct Sha256Digest([u8; 32]);
13	
14	impl Sha256Digest {
15	    /// 返回摘要的原始 32 字节。
16	    pub fn as_bytes(&self) -> &[u8; 32] {
17	        &self.0
18	    }
19	
20	    /// 返回 64 个小写十六进制字符，与命令行输出一致（不含换行）。
21	    pub fn to_hex(&self) -> String {
22	        let mut hex = String::with_capacity(64);
23	        for byte in self.0 {
24	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
25	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
26	        }
27	        hex
28	    }
29	}
30	
31	impl fmt::Display for Sha256Digest {
32	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
33	        f.write_str(&self.to_hex())
34	    }
35	}
36	
37	impl fmt::Debug for Sha256Digest {
38	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
39	        write!(f, "Sha256Digest({self})")
40	    }
41	}
42	
43	/// 计算摘要过程中读取输入失败时返回的类型化错误。
44	#[derive(Debug)]
45	pub struct DigestError(io::Error);
46	
47	impl DigestError {
48	    /// 取出底层的 I/O 错误。
49	    pub fn into_inner(self) -> io::Error {
50	        self.0
51	    }
52	}
53	
54	impl fmt::Display for DigestError {
55	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
56	        write!(f, "failed to read input: {}", self.0)
57	    }
58	}
59	
60	impl Error for DigestError {
61	    fn source(&self) -> Option<&(dyn Error + 'static)> {
62	        Some(&self.0)
63	    }
64	}
65	
66	impl From<io::Error> for DigestError {
67	    fn from(err: io::Error) -> Self {
68	        DigestError(err)
69	    }
70	}
71	
72	/// 以流式方式读取 `reader` 的全部字节并计算 SHA-256 摘要。
73	///
74	/// 内存占用与输入大小无关。读取失败时返回 [`DigestError`]，绝不返回部分内容的摘要。
75	///
76	/// [`io::ErrorKind::Interrupted`] 是临时中断而非输入结束：本次读取没有
77	/// 消费任何字节，直接重试同一位置，摘要与未发生中断时完全一致。其他
78	/// 错误（权限不足、数据损坏等）仍然立即失败。
79	pub fn digest_reader<R: Read>(mut reader: R) -> Result<Sha256Digest, DigestError> {
80	    let mut hasher = Sha256::new();
81	    let mut buf = [0u8; 64 * 1024];
82	    loop {
83	        match reader.read(&mut buf) {
84	            Ok(0) => break,
85	            Ok(n) => hasher.update(&buf[..n]),
86	            Err(ref err) if err.kind() == io::ErrorKind::Interrupted => continue,
87	            Err(err) => return Err(DigestError(err)),
88	        }
89	    }
90	    Ok(Sha256Digest(hasher.finalize().into()))
91	}
92	
93	#[cfg(test)]
94	mod tests {
95	    use super::*;
96	    use std::io;
97	
98	    #[test]
99	    fn empty_input_matches_standard_sha256() {
100	        let digest = digest_reader(io::empty()).unwrap();
101	        assert_eq!(
102	            digest.to_hex(),
103	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
104	        );
105	    }
106	
107	    #[test]
108	    fn known_vector_abc() {
109	        let digest = digest_reader(&b"abc"[..]).unwrap();
110	        assert_eq!(
111	            digest.to_hex(),
112	            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
113	        );
114	    }
115	
116	    #[test]
117	    fn binary_and_non_utf8_bytes_hashed_verbatim() {
118	        let data: Vec<u8> = (0u8..=255).chain([0x00, 0xff, 0xfe, 0x80]).collect();
119	        let digest = digest_reader(&data[..]).unwrap();
120	        // 独立依据：python3 hashlib.sha256 对同样 260 字节的计算结果。
121	        assert_eq!(
122	            digest.to_hex(),
123	            "ae1754116b130744d081ccc09988962b3e875ec0e0d6194f2c950e8fe7e27a3d"
124	        );
125	        assert_eq!(digest.to_hex().len(), 64);
126	        assert!(digest.to_hex().chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
127	    }
128	
129	    #[test]
130	    fn read_failure_is_typed_error_not_digest() {
131	        struct FailingReader;
132	        impl Read for FailingReader {
133	            fn read(&mut self, _buf: &mut [u8]) -> io::Result<usize> {
134	                Err(io::Error::new(io::ErrorKind::Other, "boom"))
135	            }
136	        }
137	        let err = digest_reader(FailingReader).unwrap_err();
138	        assert!(err.to_string().contains("boom"));
139	    }
140	
141	    /// 按给定片段长度序列依次返回输入字节的读取器；序列为空时每次读满。
142	    /// 用于模拟不同分块方式，验证摘要只取决于字节内容而非读取方式。
143	    struct ChunkedReader<'a> {
144	        data: &'a [u8],
145	        pos: usize,
146	        chunk_sizes: &'a [usize],
147	        chunk_index: usize,
148	    }
149	
150	    impl<'a> ChunkedReader<'a> {
151	        fn new(data: &'a [u8], chunk_sizes: &'a [usize]) -> Self {
152	            ChunkedReader { data, pos: 0, chunk_sizes, chunk_index: 0 }
153	        }
154	    }
155	
156	    impl Read for ChunkedReader<'_> {
157	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
158	            if self.pos == self.data.len() {
159	                return Ok(0);
160	            }
161	            let mut limit = buf.len();
162	            if !self.chunk_sizes.is_empty() {
163	                limit = limit.min(self.chunk_sizes[self.chunk_index % self.chunk_sizes.len()]);
164	                self.chunk_index += 1;
165	            }
166	            let n = limit.min(self.data.len() - self.pos);
167	            buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
168	            self.pos += n;
169	            Ok(n)
170	        }
171	    }
172	
173	    /// 确定性长输入：长度 3*64KiB + 1234，保证跨越多次内部读取且末尾留有不整段的尾巴。
174	    fn long_input() -> Vec<u8> {
175	        (0..(3 * 64 * 1024 + 1234))
176	            .map(|i| ((i * 31 + 7) % 256) as u8)
177	            .collect()
178	    }
179	
180	    /// 独立依据：python3 hashlib.sha256 对 long_input() 全部字节的计算结果。
181	    const LONG_INPUT_HEX: &str =
182	        "8ca02b16ce35f9fca993a0fdf5a537fc72a62a77b2e6fa852a371f18b8e3fcc4";
183	
184	    #[test]
185	    fn long_input_digest_covers_all_bytes_including_tail() {
186	        let digest = digest_reader(&long_input()[..]).unwrap();
187	        assert_eq!(digest.to_hex(), LONG_INPUT_HEX);
188	    }
189	
190	    #[test]
191	    fn chunking_strategy_does_not_change_digest() {
192	        let data = long_input();
193	        let expected = digest_reader(&data[..]).unwrap();
194	
195	        // 每次只给少量字节（1 字节），读取器必须被持续读取直到报告结束。
196	        let one_byte = digest_reader(ChunkedReader::new(&data, &[1])).unwrap();
197	        // 每次少量但不等的字节数。
198	        let small_uneven = digest_reader(ChunkedReader::new(&data, &[1, 2, 3, 5, 7])).unwrap();
